html:
{% set plant_print_label = frappe.db.get_single_value("CCPC Approval Settings", "plant_manager_print_label") or "JPR" %}
{% set coo_print_label = frappe.db.get_single_value("CCPC Approval Settings", "coo_print_label") or "JGG" %}
{% set gm_print_label = frappe.db.get_single_value("CCPC Approval Settings", "general_manager_print_label") or "Approved by:" %}
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") if doc.company else None %}
<style>
.print-format {
  orientation: Landscape;
  page-size: A4;
  margin-top: 6mm;
  margin-bottom: 5mm;
  margin-left: 6mm;
  margin-right: 6mm;
  font-family: Arial, sans-serif;
  font-size: 10px;
  color: #000;
}
.mrs-sheet { width: 100%; }
.mrs-sheet table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.mrs-header td { border: 0; vertical-align: top; }
.mrs-logo { width: 24%; height: 44px; }
.mrs-logo img { max-height: 42px; max-width: 120px; }
.mrs-title { width: 50%; text-align: center; vertical-align: bottom !important; font-size: 14px; padding-top: 20px; }
.mrs-control { width: 26%; font-size: 8.5px; line-height: 1.45; text-align: left; padding-left: 12px; }
.meta-row { margin-top: 2px; margin-bottom: 4px; display: table; width: 100%; }
.meta-cell { display: table-cell; vertical-align: bottom; }
.meta-label { font-weight: 600; }
.underline { border-bottom: 1px solid #000; display: inline-block; min-width: 145px; padding: 0 4px 2px; }
.items th, .items td { border: 1px solid #000; padding: 3px 4px; vertical-align: middle; }
.items th { text-align: center; font-weight: 600; font-size: 9.5px; }
.items td { height: 26px; font-size: 9px; }
.items .blank-row td { height: 25px; }
.items .center { text-align: center; }
.justification { border: 1px solid #000; border-top: 0; min-height: 58px; padding: 3px 4px; }
.justification-title { font-weight: 600; margin-bottom: 3px; }
.bottom-grid { border: 1px solid #000; border-top: 0; }
.bottom-grid td { vertical-align: top; padding: 4px 5px; }
.bottom-left { width: 25%; border-right: 1px solid #000; }
.bottom-middle { width: 35%; border-right: 1px solid #000; }
.bottom-right { width: 40%; }
.check-row { margin-top: 8px; line-height: 1.8; }
.check-box { display: inline-block; width: 12px; height: 12px; line-height: 11px; text-align: center; border: 1px solid #000; margin-right: 3px; font-size: 10px; vertical-align: middle; }
.sig-row { margin-top: 11px; }
.sig-line { border-bottom: 1px solid #000; height: 15px; margin: 0 4px 2px; }
.sig-caption { text-align: center; font-size: 9px; }
.sig-name { text-align: center; font-size: 8.5px; margin-top: 1px; }
.authorized-title { text-align: center; font-weight: 600; margin-bottom: 13px; }
.authorized { width: 100%; }
.authorized td { padding: 0 5px; width: 33.333%; }
.footer-copies { font-size: 8.5px; margin-top: 3px; }
.small-context { font-size: 8px; margin-top: 5px; line-height: 1.3; }
</style>

<div class="mrs-sheet">
  <table class="mrs-header">
    <tr>
      <td class="mrs-logo">
        {% if company_logo %}
          <img src="{{ frappe.get_url(company_logo) }}" alt="CCPC Logo">
        {% elif doc.company %}
          <strong>{{ doc.company }}</strong>
        {% endif %}
      </td>
      <td class="mrs-title">MATERIAL REQUISITION SLIP</td>
      <td class="mrs-control">
        <div>CCPC PUR-F-001</div>
        <div>Revision No.00</div>
        <div>Effectivity Date: August 25, 2023</div>
      </td>
    </tr>
  </table>

  <div class="meta-row">
    <div class="meta-cell" style="width:34%;">
      <span class="meta-label">Date:</span>
      <span class="underline">{{ frappe.utils.formatdate(doc.request_date, "dd MMM yyyy") if doc.request_date else "" }}</span>
    </div>
    <div class="meta-cell" style="width:32%; text-align:center;"></div>
    <div class="meta-cell" style="width:34%; text-align:right;">
      <span class="meta-label">MRS#</span>
      <span class="underline" style="min-width:165px;">{{ doc.name }}</span>
    </div>
  </div>

  <table class="items">
    <thead>
      <tr>
        <th style="width:4%;">Item<br>#</th>
        <th style="width:40%;">DESCRIPTION</th>
        <th style="width:7%;">Qty</th>
        <th style="width:9%;">Unit</th>
        <th style="width:12%;">Price</th>
        <th style="width:13%;">Date Needed</th>
        <th style="width:15%;">Remarks</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="center">{{ row.idx }}</td>
        <td>
          {{ row.item_name or row.item_code or "" }}
          {% if row.description and row.description != row.item_name %}
            <div style="font-size:8px;">{{ row.description }}</div>
          {% endif %}
        </td>
        <td class="center">{{ row.get_formatted("requested_qty", doc) }}</td>
        <td class="center">{{ row.uom or "" }}</td>
        <td>&nbsp;</td>
        <td class="center">{{ frappe.utils.formatdate(row.date_needed, "dd MMM yyyy") if row.date_needed else "" }}</td>
        <td>{{ row.remarks or "" }}</td>
      </tr>
      {% endfor %}
      {% set blank_rows = 10 - (doc.items|length) %}
      {% if blank_rows > 0 %}
        {% for i in range(blank_rows) %}
        <tr class="blank-row">
          <td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  <div class="justification">
    <div class="justification-title">Justification</div>
    <div>{{ doc.justification or "" }}</div>
  </div>

  <table class="bottom-grid">
    <tr>
      <td class="bottom-left">
        <div><strong>Dept. End User:</strong></div>
        <div class="sig-line" style="margin-top:8px;"></div>
        <div class="sig-name">{{ doc.use_department or "" }}</div>

        <div class="check-row">
          <span class="check-box">{% if doc.request_category == "Maintenance" %}✓{% endif %}</span> Maintenance
          &nbsp;&nbsp;
          <span class="check-box">{% if doc.request_category == "Others" %}✓{% endif %}</span> Others
          <br>
          <span class="check-box">{% if doc.request_category == "Project" %}✓{% endif %}</span> Project
        </div>

        {% if doc.equipment or doc.work_request or doc.job_order or doc.physical_location %}
        <div class="small-context">
          {% if doc.equipment %}<div>Equipment: {{ doc.equipment }}</div>{% endif %}
          {% if doc.work_request %}<div>Work Request: {{ doc.work_request }}</div>{% endif %}
          {% if doc.job_order %}<div>Job Order: {{ doc.job_order }}</div>{% endif %}
          {% if doc.physical_location %}<div>Location: {{ doc.physical_location }}</div>{% endif %}
        </div>
        {% endif %}
      </td>

      <td class="bottom-middle">
        <div class="sig-row" style="margin-top:10px;">
          <div><strong>Prepared by:</strong></div>
          <div class="sig-line"></div>
          <div class="sig-name">{{ doc.prepared_by_name or "" }}</div>
        </div>

        <div class="sig-row" style="margin-top:13px;">
          <div><strong>Verified / Recommended by:</strong></div>
          <div class="sig-line"></div>
          <div class="sig-name">
            {{ doc.requesting_department_manager_name or "" }}
            {% if doc.use_department_manager_name and doc.use_department_manager_name != doc.requesting_department_manager_name %}
              <br>Use Dept. Manager: {{ doc.use_department_manager_name }}
            {% endif %}
          </div>
          <div class="sig-caption">Department Manager</div>
        </div>
      </td>

      <td class="bottom-right">
        <div class="authorized-title">Authorized By:</div>
        <table class="authorized">
          <tr>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ plant_print_label }}</div>
            </td>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ coo_print_label }}</div>
            </td>
            <td>
              <div class="sig-line"></div>
              <div class="sig-caption">{{ gm_print_label }}</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <div class="footer-copies">
    Original Copy - Purchasing
    <span style="margin-left:90px;">Duplicate - Stockroom</span>
  </div>
</div>
